  const enable=document.createElement('input');enable.type='checkbox';enable.checked=required||included;enable.setAttribute('aria-label','Include '+name);
  const label=document.createElement('label');label.textContent=name;const status=document.createElement('small');status.textContent=required?'Required':'Optional';head.append(label,status);if(!required)head.prepend(enable);
  const editor=valueEditor(schema,value,path);label.htmlFor='field-'+path;
  const setEnabled=()=>{editor.node.classList.toggle('hidden',!enable.checked);updatePreview()};enable.onchange=setEnabled;editor.node.classList.toggle('hidden',!enable.checked);node.append(head,editor.node);
  if(schema.description){const hint=document.createElement('div');hint.className='hint';hint.textContent=schema.description;node.append(hint)}
  return {node,read:()=>{if(!enable.checked)return undefined;const v=editor.read();if(required&&typeof v==='string'&&!v.trim())throw Error('Fill in '+name);return v}};
