$('operation-form').onsubmit=e=>{e.preventDefault();runRequest()};$('operation-form').oninput=updatePreview;
$('save-current').onclick=()=>{try{saveRecord(readFields(),false,true)}catch(e){$('modal-notice').textContent=e.message}};
$('clear-runs').onclick=()=>{const c=connections[active];c.history[current.id]=history().filter(r=>r.saved);renderRuns()};
$('clear-saved').onclick=()=>{const c=connections[active];c.history[current.id]=history().filter(r=>!r.saved);renderRuns()};
$('connection-form').onsubmit=e=>{
  e.preventDefault();const name=$('name').value.trim();if(!name)return;
  if($('connection-dialog').open&&!editing||!connections.length){connections.push({id:nextConnection++,name,mode:'client',url:$('url').value,connected:true,history:{},leases:{}});active=connections.length-1}
  else{connections[active].name=name;connections[active].url=$('url').value;connections[active].connected=true}
  if($('connection-dialog').open)$('connection-dialog').close();show();tabs();
};
$('test').onclick=()=>{$('connect-notice').textContent='Simulated test passed. No tab is added until you click Connect.'};
$('search').oninput=render;$('all').onclick=()=>{availableOnly=false;render()};$('available').onclick=()=>{availableOnly=true;render()};
$('edit').onclick=()=>openConnection(true);$('remove-active').onclick=()=>removeConnection(active);$('remove-setup').onclick=()=>removeConnection(active);
$('cancel').onclick=()=>$('modal').close();
$('switch').onclick=()=>{const target=mode==='client'?'server':'client';let i=connections.findIndex(c=>c.mode===target);if(i<0){connections.push({id:nextConnection++,name:target==='server'?'Dedicated server':'Local Fabric client',mode:target,connected:true,history:{},leases:{}});i=connections.length-1}active=i;connections[i].connected=true;show();tabs()};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('response-body').textContent);$('copy').textContent='Copied'}catch{$('copy').textContent='Select JSON to copy'}};
const view=new URLSearchParams(location.search).get('view');if(view==='setup')connections[0].connected=false;if(view==='client'||view==='server'){active=view==='server'?1:0;connections[active].connected=true}tabs();show();

function sizeInspector(){
  const side=document.querySelector('.side');if(!side||$('connected').classList.contains('hidden'))return;
  const top=side.getBoundingClientRect().top+window.scrollY;
  const available=innerWidth>720?Math.max(240,innerHeight-top-24):innerHeight-32;
  side.style.setProperty('--inspector-height',Math.round(available)+'px');
}
window.addEventListener('resize',sizeInspector);
const inspectorObserver=new ResizeObserver(()=>requestAnimationFrame(sizeInspector));
inspectorObserver.observe(document.querySelector('.statusbar'));inspectorObserver.observe(document.querySelector('.toolbar'));
requestAnimationFrame(sizeInspector);
